(()=>{'use strict';
if(window.__CCNER_CLINICAL_INTELLIGENCE__)return;window.__CCNER_CLINICAL_INTELLIGENCE__=true;
const KEY='ccner-clinical-profile.v1',REPORTS='ccner-clinical-reports.v1';
const $=(s,r=document)=>r.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const domains=['memory','attention','executive','language','visuospatial','orientation','function','mood'];
const labels={memory:'Memory',attention:'Attention',executive:'Executive / planning',language:'Language / communication',visuospatial:'Visuospatial',orientation:'Orientation',function:'Daily function',mood:'Mood / engagement'};
const gameMap={sequence:'memory',stroop:'attention',house:'executive',pattern:'executive',spot:'visuospatial'};
const plan={memory:[['Sequence Memory','Short, structured recall practice; keep difficulty gentle and review progress over time.'],['Family Stories','Use real family memories for reminiscence and meaningful conversation.']],attention:[['Stroop Test','Brief attention/concentration practice with clear instructions and rest breaks.'],['Spot the Difference','Visual attention practice; stop if the task becomes frustrating.']],executive:[['Around the House Sorting','Everyday-item and planning practice that connects to familiar routines.'],['Pattern Recognition','Short problem-solving practice with adjustable difficulty.']],language:[['Talk to Momo','Use simple voice conversation and allow extra response time.'],['Family Stories','Encourage familiar conversation rather than testing recall repeatedly.']],visuospatial:[['Spot the Difference','Short visual-search tasks with larger, high-contrast targets.'],['Pattern Recognition','Simple visual/pattern tasks with gradual challenge.']],orientation:[['Reminders','Use medication, hydration, appointment and daily-activity reminders.'],['Momo','Use calm orientation prompts: date, time, place and next activity.']],function:[['Daily reminders','Support routines with external memory aids rather than relying on recall alone.'],['Caregiver check-ins','Track changes in everyday functioning and escalate concerns to a professional.']],mood:[['Family Stories','Meaningful reminiscence using real family memories.'],['Music Memory','Familiar, preferred music can support engagement and social connection.']]};
function readProfile(){try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch(_){return null}}
function writeProfile(p){try{localStorage.setItem(KEY,JSON.stringify(p))}catch(_){}window.dispatchEvent(new CustomEvent('ccner:clinical-profile-updated',{detail:p}))}
function gameProfile(){let h=[];try{h=JSON.parse(localStorage.getItem('ccner-history')||'[]')}catch(_){}const out={},sums={};domains.forEach(d=>out[d]=null);for(const s of(Array.isArray(h)?h:[])){for(const r of(s.results||[])){const d=gameMap[r.game];if(!d)continue;(sums[d]??=[]).push(r.correct?1:0)}}Object.entries(sums).forEach(([d,a])=>out[d]=a.reduce((x,y)=>x+y,0)/a.length);return out}
function localAnalyze(text){const l=text.toLowerCase(),signals={};const hit=terms=>terms.some(x=>l.includes(x));const rules={memory:['memory loss','forgetful','forgetfulness','recall','repeats','repeated question','short-term memory','recent events'],attention:['attention','concentration','distract','inattentive','focus'],executive:['planning','problem solving','executive','judgment','multistep','organisation','organization','sequencing'],language:['aphasia','word finding','word-finding','language','speech','communication','names words'],visuospatial:['visuospatial','spatial','getting lost','navigation','objects','visual'],orientation:['disoriented','orientation','date','time','place','person','confusion'],function:['activities of daily living','adl','iadl','instrumental activities','needs help','needs assistance','dependent','independent','dressing','bathing','medication management','shopping','cooking'],mood:['depression','anxiety','apathy','agitation','irritable','withdrawn','mood','sleep']};Object.entries(rules).forEach(([d,terms])=>{if(hit(terms))signals[d]={concern:true,confidence:.65,evidence:terms.filter(x=>l.includes(x)).slice(0,3)}});const stage=(l.match(/\b(gds|global deterioration scale)\s*(?:stage)?\s*([1-7])\b/)||[]),cdr=(l.match(/\b(?:cdr|clinical dementia rating)\s*(?:score|=|:)?\s*(0(?:\.5)?|1|2|3)\b/)||[]),moca=(l.match(/\bmoca\s*(?:score|=|:)\s*(\d{1,2})\b/)||[]),mmse=(l.match(/\bmmse\s*(?:score|=|:)\s*(\d{1,2})\b/)||[]);const explicit=[];if(stage[2])explicit.push({scale:'GDS',value:Number(stage[2]),source:'report text'});if(cdr[1])explicit.push({scale:'CDR',value:Number(cdr[1]),source:'report text'});if(moca[1])explicit.push({scale:'MoCA',value:Number(moca[1]),source:'report text'});if(mmse[1])explicit.push({scale:'MMSE',value:Number(mmse[1]),source:'report text'});const redFlags=['sudden confusion','acute confusion','delirium','new weakness','stroke','fall','hallucination','fainting','seizure'].filter(x=>l.includes(x));return{version:1,source:'local-text-analysis',analyzedAt:new Date().toISOString(),domains:signals,explicitClinicalMeasures:explicit,redFlags,functionalImpact:signals.function?'Report contains functional/ADL information.':'Functional impact not established from the supplied text.',confidenceNote:'Keyword analysis is a fallback only; it is not a clinical assessment.'}}
function normalize(x,text){const base=localAnalyze(text);if(!x||typeof x!=='object')return base;const d={};domains.forEach(k=>{const v=x.domains?.[k];if(v)d[k]={concern:!!v.concern,confidence:clamp(Number(v.confidence??.6)),evidence:Array.isArray(v.evidence)?v.evidence.slice(0,4).map(String):[]}});return{...base,...x,version:1,analyzedAt:new Date().toISOString(),domains:Object.keys(d).length?d:base.domains,explicitClinicalMeasures:Array.isArray(x.explicitClinicalMeasures)?x.explicitClinicalMeasures.slice(0,8):base.explicitClinicalMeasures,redFlags:Array.isArray(x.redFlags)?x.redFlags.slice(0,8):base.redFlags}}
async function aiAnalyze(text){const prompt=`You are the clinical-structure layer of a dementia support app. Analyze ONLY the supplied report text. Do not diagnose, stage, prescribe medication, or invent facts. Extract documented concerns by domain and explicit clinician-reported scores/stages. Return JSON only with this shape: {"domains":{"memory":{"concern":true,"confidence":0.0,"evidence":["brief paraphrase"]},"attention":{},"executive":{},"language":{},"visuospatial":{},"orientation":{},"function":{},"mood":{}},"explicitClinicalMeasures":[{"scale":"GDS|CDR|MoCA|MMSE|other","value":"reported value","source":"clinician/report"}],"redFlags":["only acute/safety concerns actually mentioned"],"functionalImpact":"brief documented summary","notes":["brief caveat"]}. Confidence means confidence that the report text documents a concern, NOT probability of disease. Report text:\n\n${text.slice(0,30000)}`;try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompt,history:[],level:1,screen:'clinical-report-analyzer',game:null})});if(!r.ok)throw 0;const j=await r.json();const raw=j?.reply||j?.content||'',m=String(raw).match(/\{[\s\S]*\}/);if(m)return JSON.parse(m[0])}catch(_){}return null}
async function saveCloud(reportTitle,analysis){try{const c=window.CCNERAuth?.client?.(),sess=await c?.auth?.getSession(),uid=sess?.data?.session?.user?.id;if(!c||!uid)return false;const{error}=await c.from('clinical_reports').insert({user_id:uid,report_title:reportTitle||'Clinical report',source_type:'text',analysis});return!error}catch(_){return false}}
function openModal(mode='report'){if($('#ccnerClinicalModal')){renderTab(mode);return}document.body.insertAdjacentHTML('beforeend',`<section id="ccnerClinicalModal" class="ccner-clinical-modal" role="dialog" aria-modal="true"><div class="ccner-clinical-card"><button class="ccner-clinical-close" id="ccnerClinicalClose">×</button><div class="ccner-clinical-head"><div><span class="ci-kicker">CLINICAL INTELLIGENCE</span><h2>Report → care-support alignment</h2><p>Structure what is documented, connect it to training and support, and keep clinician judgment in the loop.</p></div><span class="ci-badge">SAFETY FIRST</span></div><div class="ci-tabs"><button data-ci-tab="report">Analyze report</button><button data-ci-tab="plan">Care-support plan</button></div><div id="ccnerClinicalBody"></div></div></section>`);$('#ccnerClinicalClose').onclick=()=>$('#ccnerClinicalModal')?.remove();document.querySelectorAll('[data-ci-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.ciTab));renderTab(mode)}
function renderTab(mode){const body=$('#ccnerClinicalBody');if(!body)return;if(mode==='plan')return renderPlan(body);body.innerHTML=`<div class="ci-consent"><b>Use with clinician/caregiver oversight.</b> Reports can contain sensitive health information. The AI request is sent only when you press Analyze. The original report text is not stored by this module.</div><label class="ci-label">Report title<input id="ciTitle" class="ci-input" placeholder="e.g. Neurology follow-up · Sept 2026"></label><label class="ci-label">Paste report text<textarea id="ciText" class="ci-textarea" placeholder="Paste the relevant report, assessment, or clinician note here…"></textarea></label><label class="ci-check"><input id="ciConsent" type="checkbox"> I understand this is decision support, not a diagnosis or treatment recommendation.</label><button id="ciAnalyze" class="ci-primary">Analyze & align</button><div id="ciStatus" class="ci-status"></div><div id="ciOutput"></div>`;$('#ciAnalyze').onclick=analyzeFromUI}
async function analyzeFromUI(){const text=$('#ciText')?.value?.trim(),title=$('#ciTitle')?.value?.trim()||'Clinical report';if(!text)return setStatus('Paste report text first.',true);if(!$('#ciConsent')?.checked)return setStatus('Please confirm the decision-support notice first.',true);const b=$('#ciAnalyze');b.disabled=true;setStatus('Structuring report…');const ai=await aiAnalyze(text),analysis=normalize(ai,text);analysis.gamePerformance=gameProfile();analysis.priorityDomains=domains.filter(d=>analysis.domains?.[d]?.concern).sort((a,b)=>(analysis.domains[b]?.confidence||0)-(analysis.domains[a]?.confidence||0));writeProfile(analysis);try{const recent=JSON.parse(localStorage.getItem(REPORTS)||'[]');recent.unshift({title,at:analysis.analyzedAt,analysis});localStorage.setItem(REPORTS,JSON.stringify(recent.slice(0,5)))}catch(_){}const saved=await saveCloud(title,analysis);b.disabled=false;setStatus(saved?'Analysis complete · structured summary saved securely.':'Analysis complete · local summary only.');renderAnalysis(analysis)}
function setStatus(t,bad=false){const e=$('#ciStatus');if(e){e.textContent=t;e.className='ci-status'+(bad?' bad':'')}}
function renderAnalysis(a){const body=$('#ccnerClinicalBody');if(!body)return;const measure=a.explicitClinicalMeasures?.length?a.explicitClinicalMeasures.map(x=>`<span>${esc(x.scale)}: <b>${esc(x.value)}</b> <small>reported</small></span>`).join(''):'<span>No explicit clinical score/stage found in the text.</span>';const rows=domains.filter(d=>a.domains?.[d]).map(d=>`<div class="ci-domain"><div><b>${labels[d]}</b><small>${esc((a.domains[d].evidence||[]).join(' · ')||'Documented concern')}</small></div><strong>${Math.round((a.domains[d].confidence||0)*100)}%</strong></div>`).join('')||'<p>No domain concerns were confidently extracted.</p>';const flags=a.redFlags?.length?`<div class="ci-warning"><b>Needs clinician attention</b><span>${esc(a.redFlags.join(' · '))}</span></div>`:'';body.innerHTML=`<div class="ci-result-head"><div><span class="ci-kicker">STRUCTURED FINDINGS</span><h3>What the report actually documents</h3></div><button class="ci-link" data-ci-tab="plan">Build care-support plan →</button></div><div class="ci-measures">${measure}</div><div class="ci-domain-list">${rows}</div>${flags}<div class="ci-note"><b>Functional impact:</b> ${esc(a.functionalImpact||'Not established from supplied text.')}</div><p class="ci-disclaimer">This does not determine dementia, severity, prognosis, or treatment. Explicit scores/stages are shown only as clinician-reported values; game performance remains a separate training signal.</p>`;body.querySelector('[data-ci-tab="plan"]')?.addEventListener('click',()=>renderTab('plan'))}
function renderPlan(body){const a=readProfile(),gp=gameProfile();if(!a){body.innerHTML=`<div class="ci-empty"><h3>No report profile yet</h3><p>Analyze a clinician report first. The plan will then combine documented concerns with the app's training history.</p><button class="ci-primary" id="ciStartReport">Analyze a report</button></div>`;$('#ciStartReport').onclick=()=>renderTab('report');return}const priorities=(a.priorityDomains?.length?a.priorityDomains:domains.filter(d=>a.domains?.[d]?.concern)).slice(0,5),cards=priorities.map(d=>`<article class="ci-plan-card"><div><span class="ci-kicker">PRIORITY</span><h3>${labels[d]}</h3></div>${(plan[d]||[]).map(x=>`<div class="ci-action"><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`).join('')}<div class="ci-train">Current training signal: ${gp[d]==null?'not enough data':Math.round(gp[d]*100)+'% task accuracy'}</div></article>`).join(''),rest=priorities.length?'':`<div class="ci-note">No specific domain concern was extracted. Continue broad, enjoyable activities and review the plan with the care team.</div>`;body.innerHTML=`<div class="ci-result-head"><div><span class="ci-kicker">PERSON-CENTRED SUPPORT</span><h3>Suggested next activities</h3></div><button class="ci-link" data-ci-tab="report">← Report</button></div><p class="ci-intro">These are app-level support activities, not prescriptions. NICE recommends personalised activities and, where appropriate, cognitive stimulation, reminiscence and cognitive rehabilitation/occupational therapy with professional oversight. The app should reinforce—not replace—that care.</p><div class="ci-plan-grid">${cards}${rest}</div><div class="ci-safety"><b>Clinician review</b><span>Use the documented report, everyday-function observations and longitudinal trends together. If there is a sudden change, new neurological symptom, delirium-like confusion, or other urgent concern, seek appropriate medical evaluation.</span></div>`;body.querySelector('[data-ci-tab]')?.addEventListener('click',()=>renderTab(body.querySelector('[data-ci-tab]').dataset.ciTab))}
function inject(){if($('#ccnerClinicalLauncher'))return;const host=$('#level3Dashboard')||$('#homeView');if(!host)return false;const quick=$('.l3-quick',host)||host.lastElementChild,card=document.createElement('section');card.id='ccnerClinicalLauncher';card.className='ci-launcher';card.innerHTML=`<div><span class="ci-kicker">CLINICAL INTELLIGENCE</span><h3>Turn reports into useful care context</h3><p>Analyze a clinician report, keep clinical scores separate from game performance, and build a person-centred support plan.</p></div><div class="ci-launch-actions"><button id="ciReportBtn" class="ci-primary">📄 Analyze a report</button><button id="ciPlanBtn" class="ci-secondary">🧭 View care-support plan</button></div>`;quick?.parentNode?.insertBefore(card,quick)||host.appendChild(card);$('#ciReportBtn').onclick=()=>openModal('report');$('#ciPlanBtn').onclick=()=>openModal('plan');return true}
function boot(){let n=0;const t=setInterval(()=>{n++;if(inject()||n>60)clearInterval(t)},1000);inject()}
window.CCNERClinical={openReport:()=>openModal('report'),openPlan:()=>openModal('plan'),getProfile:readProfile,gameProfile};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
